export const meta = {
  name: 'mega-remediation-premortem',
  description: 'Adversarial pre-mortem fleet on docs/plans/mega-remediation-20260701.md, then edit plan in place',
  phases: [
    { title: 'Find', detail: 'five adversarial lenses independently attack the plan' },
    { title: 'Verify', detail: 'skeptic refutes each finding as soon as its lens completes' },
    { title: 'Synthesize', detail: 'single agent edits the plan file in place with confirmed findings' },
  ],
}

const PLAN_PATH = 'docs/plans/mega-remediation-20260701.md'

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          packet: { type: 'string', description: 'packet id from the plan, e.g. A1, E4, V3, or "cross-cutting" if not tied to one packet' },
          issue: { type: 'string', description: 'one-sentence statement of the defect in the PLAN (not in the code)' },
          severity: { type: 'string', enum: ['low', 'medium', 'high', 'critical'] },
          evidence: { type: 'string', description: 'why this is a real planning defect — cite plan line numbers and, if a code claim is being checked, the actual current code state' },
          suggested_edit: { type: 'string', description: 'concrete text to add/change in the plan file to fix this defect' },
        },
        required: ['packet', 'issue', 'severity', 'evidence', 'suggested_edit'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    real: { type: 'boolean', description: 'true if this is a genuine planning defect that should change the plan document' },
    reasoning: { type: 'string' },
  },
  required: ['real', 'reasoning'],
}

const TOKENSAVE_NOTE = `This project mandates tokensave MCP tools over Explore agents / manual grep for ANY codebase research (checking whether a function exists, checking a file:line citation, checking call sites). Use tokensave_context, tokensave_search, tokensave_files, tokensave_callers, etc. via ToolSearch. Only use Read for the plan document itself and for gh issue bodies. Do not edit any code or the plan file in this phase — read-only investigation only.`

const LENSES = [
  {
    key: 'dependency',
    label: 'Cross-packet file/symbol conflicts',
    prompt: `You are adversarially pre-mortem-reviewing a remediation plan BEFORE any execution begins, looking for hidden conflicts between packets that the plan's own "lanes run in parallel, packets within a lane run serially" model assumes away.

Read ${PLAN_PATH} in full first.

Context: this is a Swift monorepo (the-record-suite) with packages Record-Foundation, Record-Audio, Record-ML, Record-App, Record-Presentation, Record-Pro. The plan organizes ~35 fix packets into waves/lanes intended to run with up to 4 concurrent Sonnet agents (Wave 2 = Record-Audio lane, Wave 3 = Record-ML lane, Wave 4 = App/Presentation/Pro lane, Wave 5 = MCP wiring, Wave 6 = contract-audit criticals).

Your job: find every case where two packets that the plan believes are in DIFFERENT lanes (and thus safe to run concurrently) actually touch the same file, the same symbol, or symbols with a caller/callee relationship — which would produce merge conflicts or one packet invalidating another's assumptions if run in parallel. Also flag any packet whose lane assignment looks wrong given the files it lists (e.g. a packet listed in an "App/Presentation" lane that touches an Infrastructure file also owned by another lane's packet).

Specific things worth checking:
- Wave 5 (E1-E6) touches AppAssemblerBuilders.swift and GRDBContextCache.swift/GRDBSQL.swift — does anything in Wave 2/3 also touch GRDBSQL.swift or GRDBContextCache.swift concurrently? (M1 touches GRDBSQL.swift — is M1's Wave 3 lane genuinely isolated from E2's Wave 5 GRDBSQL cache-statement edit, or do they collide on the same file even though the plan puts them in different waves that claim to run "parallel to Waves 2-3"?)
- A1/A5 both touch CoreAudioTapCaptureActor.swift / MicCaptureActorRouteChange.swift-adjacent files, and A2/A3/A4 also touch CoreAudioTapCaptureActor.swift — the plan says Wave 2 is "SERIAL — same files" which is good, but confirm the ordering given (A1 then A2 then A3 then A4 then A5 then A6 then A7) is actually safe given each packet's line-number citations (does A1's rewrite of the tap setup shift the line numbers A2/A3/A4 cite?).
- P5/P6 are explicitly "run LAST in this lane" — check whether any earlier P-packet in the same lane touches a symbol that MenuBarViewModel or InferenceMetrics.swift extensions depend on such that P5/P6 running last is still correct, or whether it should run FIRST instead.
- Wave 6 note says C-packets run "after Wave 5 (E4 touches the same assembler)" — verify this is the only cross-wave file collision, or if there are others the plan didn't call out.

Use tokensave to check actual current file contents/callers for anything ambiguous — don't guess from the plan text alone. ${TOKENSAVE_NOTE}

Report every genuine conflict you find via the findings schema. If a suspected conflict turns out to be fine on inspection, do not report it as a finding.`,
  },
  {
    key: 'citation',
    label: 'File:line citation accuracy',
    prompt: `You are adversarially pre-mortem-reviewing a remediation plan BEFORE any execution begins. Read ${PLAN_PATH} in full first.

Your job: spot-check the plan's file:line citations against the ACTUAL current state of the code on main, using tokensave (never grep/Explore — this project mandates tokensave for all codebase research). ${TOKENSAVE_NOTE}

The plan cites dozens of specific file:line locations as evidence for bugs or as edit targets (e.g. "CoreAudioTapCaptureActorSupport.swift:144", "AECProcessorActor.swift:125-170", "GRDBSQL.swift:101-108", "StartRecordingUseCase.swift:119,127", "MicCaptureActorRouteChange.swift:16-77", "SummarizationPrompts.swift:~51", etc.) Pick at least 12 of these citations spread across Wave 1 (verify-and-close), Wave 2 (audio), Wave 3 (ML), and Wave 5 (MCP), prioritizing ones that will gate whether an agent concludes ALREADY_FIXED vs writes a fix. For each: use tokensave to read the actual current file at that location and confirm whether the cited line number and described code shape (the specific pattern, e.g. "single sessionID threaded", "trailing-slash guard", "errorHandler is public let") still holds on the current main branch.

Flag any citation that is: wrong line number (code has moved), wrong file, or where the described current-state characterization is inaccurate or has already changed since the plan was written (this plan was written 2026-07-01 against a specific commit — check if HEAD has moved since, e.g. via recent commits like "fix(storage): address Codex review findings on GRDB migration" or "fix(tests): resolve all Record-ML test compilation errors" which may have shifted line numbers in Record-ML files M1-M8 reference).

Report each inaccurate citation as a finding with packet id, the wrong claim, and the corrected file:line/description to use instead.`,
  },
  {
    key: 'sequencing',
    label: 'Wave/dependency ordering correctness',
    prompt: `You are adversarially pre-mortem-reviewing a remediation plan BEFORE any execution begins. Read ${PLAN_PATH} in full first.

Your job: find ordering/sequencing assumptions in the plan that don't actually hold up. Specific things to check:

1. A1 (system tap sample-rate fix) is instructed to "mirror the #49 pattern from MicCaptureActorRouteChange.swift:16-77 (handleConfigurationChange())". Use tokensave to confirm that pattern still exists at that location and is actually mirror-able (same actor shape, same continuation/writer reuse pattern) for CoreAudioTapCaptureActor — if MicCaptureActorRouteChange.swift has since been refactored (note: A5 in the SAME plan also modifies MicCaptureActorRouteChange.swift's abortRouteChange wiring) then A1, which is supposed to run before A5 in Wave 2's stated order, might be mirroring a pattern that A5 is about to change underneath it, or A1 might need to land AFTER A5 so it mirrors the corrected (wired) abort path rather than the current leaky one. Determine the actually-correct order and flag if the plan's ordering is backwards.

2. Wave 0 (Phase 0 bookkeeping) commits several test/source fixes then creates branch fix/mega-remediation-20260701 "from main for all remaining work". Check: does Phase 0.1's own commit list depend on anything Wave 1-6 packets also touch, such that committing Phase 0 AFTER branching (rather than before, as the plan states) would matter? Confirm the stated order (commit to main first, branch after) is actually followed logically, i.e. no packet in Wave 1+ assumes Phase-0-committed state doesn't yet exist.

3. Wave 5 step E4 "Wire in AppAssembler.buildMCPProviders" depends on E1 (NotionProvider.isHealthy), E2 (cache provider-scoping), E3 (AppConfig fields) all existing first per its own numbered list — confirm the plan enforces E1→E2→E3→E4→E5→E6 as strictly serial (it says "sequenced, one packet per step" — check nothing upstream implies they could be parallelized incorrectly).

4. Wave 6 depends on Wave 5's E4 touching the assembler — check whether Wave 6's C1/C2/C3 packets have any inter-dependency on EACH OTHER (e.g. does C3's PrivacyModeProvider wiring at the composition root touch the same AppAssembler init that C1/C2 also need, requiring serial rather than the parallel execution the plan implies for "Each packet" in that wave)?

${TOKENSAVE_NOTE}

Report each real sequencing defect as a finding, with the corrected order/dependency stated explicitly in suggested_edit.`,
  },
  {
    key: 'test-gate',
    label: 'Falsifiable RED-test gate per packet',
    prompt: `You are adversarially pre-mortem-reviewing a remediation plan BEFORE any execution begins. Read ${PLAN_PATH} in full first.

The plan's ground rules mandate strict TDD: "failing test first (RED), confirm failure via the package's swift test --filter, then implement (GREEN)." Your job: go packet by packet (V1-V6, A1-A7, M1-M8b, P1-P6, E1-E6, C1-C3) and identify any packet where the stated RED test is NOT actually falsifiable/runnable as described, which would let an executing agent silently skip real TDD. Look especially for:

- Packets where the plan itself admits the test can't run headless (e.g. A1 says "behavioral CoreAudio tests can't run headless" and falls back to "source-inspection test that the observer registration exists" — is a source-inspection test a REAL red/green gate, or can it trivially pass without the fix working? Same concern for A5's "RED: source-inspection test that failure paths call it").
- Packets with NO test description at all (scan for ones missing an explicit RED/verify step — e.g. M4a/M4b/M4c, M6, M7, M8a/M8b, P2, P3 — do they have a stated verification method or just a description of the code change?).
- Wave 1 "verify-and-close" packets (V1-V6): the rule says "add a regression test only if none exists" — check whether the plan gives an agent enough signal to correctly judge "none exists" (i.e., is there a specified way to search for an existing test, or could an agent add a duplicate test or wrongly conclude no test exists)?
- C1-C3 packets: the plan says "spec lives in issue bodies" (gh issue view #211/#212/#213) — since you can run gh, actually check whether those issue bodies contain a testable acceptance criterion or are vague, which would leave the RED test undefined until execution time.

${TOKENSAVE_NOTE} You may also run \`unset GITHUB_TOKEN && gh issue view <n>\` read-only to check issue body content for C1-C3.

Report each packet lacking a genuine falsifiable gate as a finding, with a concrete suggested RED-test description to add to the plan.`,
  },
  {
    key: 'rollback',
    label: 'Failure/rollback and scope-creep safety',
    prompt: `You are adversarially pre-mortem-reviewing a remediation plan BEFORE any execution begins. Read ${PLAN_PATH} in full first.

The plan's orchestration mechanics say: "failed packets get one retry with the error trace, then escalate to Opus/main-loop." Your job: find gaps in failure handling and scope control across the whole plan:

1. What happens to a LANE (not just one packet) if a mid-lane packet fails twice and escalates? Wave 2 (Audio) and Wave 3 (ML) are explicitly serial-within-lane because later packets depend on earlier ones' file state (e.g. A2/A3/A4 all edit CoreAudioTapCaptureActor.swift after A1 changes it). The plan never states whether a stuck/escalated packet blocks the rest of its lane indefinitely, or what the abort/resume criteria are. Is this a real gap?

2. "Verify first" packets (Wave 1, and the "verify-first" ground rule generally) tell an agent to report ALREADY_FIXED if the defect doesn't reproduce. What guards against an agent wrongly concluding ALREADY_FIXED because it looked in the wrong place, misread the code, or the fix is partial? Is there a second-reviewer/spot-check step for ALREADY_FIXED claims before the plan closes the GitHub issue (Wave 7 step 5 closes issues based on agent reports)? If not, flag this — closing a real bug's issue on a false ALREADY_FIXED is a concrete failure mode.

3. Scope creep: packets like A6 (silent mic-cleaned WAV investigation) explicitly say "if the root cause is outside listed files, report back rather than fix" — good — but check OTHER packets for the same discipline. Does every investigative/ambiguous packet (M5 "OBSOLETE_POST_GRDB" check, E3's sandboxing pre-check, A1's defensive-second-layer) have an equally explicit "stop and report" instruction, or could an agent reasonably infer permission to touch files outside its packet in some of them?

4. Wave 7 step 2 (3-round adversarial review) and step 5 (issue closures) run after ALL waves — is there a defined trigger for what happens if Wave 7's adversarial review DISCONFIRMS one of the "headline fixes" (A1 rate-change or A6 silence) after Waves 2/3 already closed related issues and moved on? Does the plan have a re-open/re-fix loop, or does it just end?

Report each genuine gap as a finding with a concrete plan-text addition (e.g. an explicit escalation/abort rule, a second-reviewer requirement, a re-open loop) as the suggested_edit.`,
  },
]

function verifyPrompt(finding, lens) {
  return `You are a skeptical verifier checking ONE claimed defect in a pre-execution review of ${PLAN_PATH}, a Swift monorepo remediation plan (the-record-suite). A prior reviewer (lens: ${lens.label}) claimed:

Packet: ${finding.packet}
Issue: ${finding.issue}
Evidence given: ${finding.evidence}
Suggested edit: ${finding.suggested_edit}

Your job: try to REFUTE this. Read ${PLAN_PATH} yourself and, if the claim depends on actual code state, use tokensave (tokensave_context, tokensave_search, tokensave_files, tokensave_callers) to independently check — do not just trust the prior reviewer's evidence string. ${TOKENSAVE_NOTE} If the claim also depends on a GitHub issue body, you may run \`unset GITHUB_TOKEN && gh issue view <n>\` read-only.

Default to real=false (refuted) if you cannot independently confirm the defect is genuine and would actually change what should be written in the plan. Only set real=true if you positively confirm the defect yourself, independent of the prior reviewer's say-so.`
}

function synthesisPrompt(confirmed) {
  return `You are finalizing an adversarial pre-mortem review of ${PLAN_PATH}, a 7-wave, ~35-packet Swift remediation plan (the-record-suite monorepo) that has NOT started execution yet. A fleet of adversarial reviewers found the following CONFIRMED planning defects (each independently verified by a skeptic who tried to refute it and failed):

${JSON.stringify(confirmed, null, 2)}

Your job: read ${PLAN_PATH}, then EDIT it in place (use the Edit tool — do not rewrite the whole file, do not touch unrelated sections) to fix these confirmed defects:

1. Add a new section immediately after "## Ground rules" and before "## Phase 0" titled "## Pre-execution adversarial findings (fleet pre-mortem, 2026-07-01)" containing a bullet list of the confirmed findings grouped by packet, each as: "- **<packet>**: <issue> — <suggested fix, made concrete and actionable>".
2. For findings tied to a specific packet bullet elsewhere in the doc (Wave 1-6 tables/bullets), also add a short inline callout directly under that packet's existing bullet, in the form "  *Pre-flight (fleet pre-mortem): <one-line fix>*" — keep these terse, one line each, do not restate the whole finding.
3. If a finding implies a concrete change to file:line citations, correct those citations in place at their original location in the doc (do not just note the error in the new section — actually fix the stale citation).
4. If a finding implies a change to wave/packet ORDERING (e.g. A1 should run after A5, or two packets need to move to the same serial lane), edit the affected Wave section headers/packet order directly.
5. Do not touch the "## Estimate" section's packet count language unless a finding specifically requires it.
6. Keep the rest of the document byte-for-byte unchanged — every edit must be minimal and targeted at the specific defect it fixes.

If confirmed findings is an empty array, make no edits and just report that the plan survived the pre-mortem with no changes needed.

After editing, report back a short summary (under 150 words) of exactly what you changed and where.`
}

phase('Find')
const results = await pipeline(
  LENSES,
  (lens) => agent(lens.prompt, { label: `find:${lens.key}`, phase: 'Find', schema: FINDINGS_SCHEMA }),
  (review, lens) =>
    parallel(
      (review && review.findings ? review.findings : []).map((f) => () =>
        agent(verifyPrompt(f, lens), { label: `verify:${lens.key}`, phase: 'Verify', schema: VERDICT_SCHEMA }).then(
          (v) => ({ ...f, lens: lens.key, verdict: v })
        )
      )
    )
)

const allFindings = results.flat().filter(Boolean)
const confirmed = allFindings.filter((f) => f.verdict && f.verdict.real)
log(`${allFindings.length} candidate findings, ${confirmed.length} confirmed after adversarial verify`)

phase('Synthesize')
const synthesis = confirmed.length
  ? await agent(synthesisPrompt(confirmed), { label: 'synthesize', phase: 'Synthesize' })
  : 'No confirmed findings — plan left unchanged.'

return {
  totalCandidates: allFindings.length,
  confirmedCount: confirmed.length,
  confirmed,
  synthesis,
}

